"""Render-first Converse slice for the additive Operator vNext surface."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any
import re


@dataclass
class ConversationTransition:
    active_id: str | None = None
    requested_id: str | None = None
    generation: int = 0
    status: str = "idle"
    unavailable: set[str] = field(default_factory=set)

    @property
    def active_conversation_id(self) -> str | None:
        return self.active_id

    @property
    def requested_conversation_id(self) -> str | None:
        return self.requested_id

    def request(self, conversation_id: str) -> int:
        self.generation += 1
        self.requested_id = conversation_id
        self.status = "loading"
        return self.generation

    def settle(self, generation: int, conversation_id: str, success: bool) -> bool:
        if generation != self.generation or conversation_id != self.requested_id:
            return False
        if success:
            self.active_id = conversation_id
        else:
            self.unavailable.add(conversation_id)
            self.requested_id = self.active_id
        self.status = "idle"
        return True

    def succeed(self, conversation_id: str, generation: int) -> bool:
        return self.settle(generation, conversation_id, True)

    def fail(self, conversation_id: str, generation: int) -> bool:
        return self.settle(generation, conversation_id, False)

    def can_send(self, visible_id: str | None) -> bool:
        return self.status == "idle" and visible_id == self.active_id == self.requested_id

    def payload(self, visible_id: str, message: str) -> dict[str, str] | None:
        return {"conversation_id": visible_id, "message": message} if self.can_send(visible_id) else None


def transition_snapshot(model: ConversationTransition) -> dict[str, Any]:
    return {"requestedConversationId": model.requested_id, "activeConversationId": model.active_id, "conversationTransition": {"status": model.status, "generation": model.generation}, "unavailable": sorted(model.unavailable)}

